package app.wingtipmaps.android.api

import app.wingtipmaps.android.api.generated.gateway.PilotDto

// The planner's and the gateway's answers the app reads, every one
// generated from their OpenAPI documents (services/planner/openapi.json,
// services/gateway/openapi.json) into api/generated by
// scripts/build/api-models-apps.sh, as the web's types are, so a field a
// server renames fails the build rather than a screen. The names the app
// has always used are typealiases of them here; none is written by hand.
// Every figure in them is the server's; the app shows it.

/** The pilot, as the gateway knows them (PilotDto). */
typealias Pilot = PilotDto

/** Which chart the map draws and where its tiles are, and each kind of
 *  FAA chart with the zooms it has tiles for. */
typealias ChartInfo = app.wingtipmaps.android.api.generated.ChartInfo
typealias ChartLayer = app.wingtipmaps.android.api.generated.ChartLayer

/** The cycle's FAA overlays as one PMTiles archive the planner builds
 *  (wingtip.vector_tiles): its name, which its address takes, its zooms
 *  and its layers. */
typealias OverlayTiles = app.wingtipmaps.android.api.generated.OverlayTiles

/** A field in the map's view (AirportPin): the planner's, or the engine's
 *  from the cycle packs, which writes the same shape (InView.kt). */
typealias AirportPin = app.wingtipmaps.android.api.generated.AirportPin

/** A field found by ident or name. */
typealias AirportSuggestion = app.wingtipmaps.android.api.generated.AirportSuggestion

/** A METAR as the planner reads it, with the report as sent. */
typealias Metar = app.wingtipmaps.android.api.generated.Metar

/** A field's card: its weather, runways, frequencies and pattern. */
typealias AirportPlace = app.wingtipmaps.android.api.generated.AirportPlace

/** A field near a point (/api/airports/nearest), nearest first: its
 *  distance and true bearing from the point, its elevation. */
typealias NearestAirport = app.wingtipmaps.android.api.generated.NearestAirport

/** A route's two ends and its stops, as /api/course gives them
 *  (AirportEnd), and the route as entered with the great-circle line
 *  between them as pairs of latitude and longitude (Course). */
typealias CourseEnd = app.wingtipmaps.android.api.generated.AirportEnd
typealias Course = app.wingtipmaps.android.api.generated.Course

/** One of the planner's airplane types and the handbook figures it flies
 *  on (AircraftProfile, the JSON files under data/aircraft), and the
 *  summary /api/aircraft-profiles lists each by. */
typealias AircraftProfile = app.wingtipmaps.android.api.generated.AircraftProfile
typealias AircraftProfileSummary = app.wingtipmaps.android.api.generated.AircraftProfileSummary

/** One leg of the nav log, with the figures its row shows (Leg). */
typealias Leg = app.wingtipmaps.android.api.generated.Leg

/** The flight's totals and its fuel check (navlog.totals, fuel_plan): the
 *  reserve it is held to is the planner's (14 CFR 91.151, in the planner). */
typealias NavLogTotals = app.wingtipmaps.android.api.generated.Totals

/** Why no route can be flown, in the planner's words (the "error" line). */
typealias NavLogError = app.wingtipmaps.android.api.generated.NavLogError
